declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    enable : BOOL;
    rawValue : REAL;
END_VAR
VAR_OUTPUT
    filteredValue : REAL;
    windowFull : BOOL;
    sampleCount : INT;
END_VAR
VAR
    buf : ARRAY[1..8] OF REAL;
    wr : INT;
    i : INT;
    sum : REAL;
    keep : REAL;
END_VAR

implementation:
IF NOT enable THEN
    FOR i := 1 TO 8 DO
        buf[i] := 0.0;
    END_FOR
    wr := 0;
    sampleCount := 0;
    windowFull := FALSE;
ELSE

    wr := wr + 1;
    IF wr > 8 THEN
        wr := 1;
    END_IF
    buf[wr] := rawValue;
    IF sampleCount < 8 THEN
        sampleCount := sampleCount + 1;
    END_IF
    windowFull := sampleCount >= 8;


    sum := 0.0;
    FOR i := 1 TO sampleCount DO
        sum := sum + buf[i];
    END_FOR
    keep := sum / INT_TO_REAL(sampleCount);
END_IF

filteredValue := keep;
